See the REQUIRED_INFO for the variables that fill the JSON prompt: @REQUIRED_INFO

CRITICAL: Be sure to use the exact label text on product subject @text

{
"image_type": "Amazon product listing infographic — size & value comparison",
"aspect_ratio": "1:1",
"visual_purpose": "Clearly display the featured product’s size and value advantage compared to standard competitor products using a clean, infographic-style layout optimized for Amazon",

"brand_identity": {
"brand_name": "{{BRAND_NAME}}",
"brand_feel": "{{BRAND_FEEL}}",
"inspiration": "{{BRAND_INSPIRATION}}",
"tone": "{{BRAND_TONE}}"
},

"inputs": {
"reference_product_image": {
"type": "image",
"required": true,
"description": "High-resolution reference image of the featured product. Use this image as the exact subject. Preserve shape, proportions, labels, colors, materials, branding, and packaging details exactly. No redesign or stylization."
},

"competitor_product_placeholder": {
"type": "visual_placeholder",
"required": true,
"description": "Generic, unbranded competitor product silhouettes. Neutral grey color. Viewed straight-on from the same angle as the featured product. Clearly smaller in perceived size."
}
},

"comparison_variables": {
"competitor_heading": "{{COMPETITOR_HEADING}}",
"featured_heading": "{{FEATURED_HEADING}}",

"competitor_metric_text": "{{COMPETITOR_METRIC_TEXT}}",
"featured_metric_text": "{{FEATURED_METRIC_TEXT}}",

"value_callout_text": "{{VALUE_CALLOUT_TEXT}}",

"relative_size_multiplier": "{{SIZE_MULTIPLIER}}",

"comparison_metric_type": "{{COMPARISON_METRIC_TYPE}}"
},

"composition": {
"layout": "split vertical infographic layout with a clear center divider",
"product_scale": "products take up the majority of the frame, tall and dominant, similar to classic Amazon size-comparison images",
"camera_angle": "straight-on, eye-level for both competitor and featured products"
},

"left_side": {
"heading_text": "{{COMPETITOR_HEADING}}",
"heading_style": "clean, modern sans-serif, uppercase",
"product_display": "competitor product silhouettes",
"supporting_text": "{{COMPETITOR_METRIC_TEXT}}",
"visual_treatment": "muted, neutral, understated"
},

"right_side": {
"heading_text": "{{FEATURED_HEADING}}",
"heading_style": "clean, modern sans-serif, uppercase, slightly more prominent",
"product_display": "featured products from reference image",
"supporting_text": "{{FEATURED_METRIC_TEXT}}",
"visual_treatment": "confident, clear, uncluttered"
},

"value_callout": {
"text": "{{VALUE_CALLOUT_TEXT}}",
"style": "bold, large, high-contrast sans-serif",
"graphic_element": "solid directional arrow pointing from left (competitor) to right (featured product)",
"placement": "centered horizontally across the divider, not overlapping labels",
"tone": "informational, not aggressive"
},

"background": {
"name": "Golden Hour Tide Pool",
"description": "A natural tide pool on a rocky shore, filled with clear ocean water reflecting deep blue sky and warm orange tones. Glittering specular highlights from the low sun appear on the water surface. Subtle seaweed and small shells are visible.",
"treatment": "heavily blurred and softened to avoid distraction",
"purpose": "adds warmth and brand mood without competing with the infographic"
},

"color_palette": {
"primary": "clean whites and soft neutrals",
"accent": "{{BRAND_ACCENT_COLOR}}",
"competitor": "neutral grey",
"text_color": "deep charcoal or dark neutral for clarity"
},

"realism_constraints": {
"avoid": [
"3D CGI look",
"overly glossy lighting",
"decorative textures on text",
"busy overlays",
"lifestyle posing"
],
"target": "clean, realistic, Amazon-native infographic"
},

"final_instruction": "Generate a clean, straight-on Amazon infographic-style image that mirrors a classic size comparison layout. The products should dominate the frame, the comparison message should be instantly clear, and the background should remain blurred and secondary. Emphasize the featured product's value advantage using the supplied comparison metrics without visual noise or artificial styling. The featured product should appear approximately {{SIZE_MULTIPLIER}} times larger than the competitor reference while remaining moderately realistic and visually believable."
}

